# Code generated by Claude
"""
Tests of the home pose ("zombie pose") the staging ends in: both arms at home at the handoff, clear of everything, the neck framing the beaker, the
hotplate and both grippers, and the optional random variation of the home pose.

    MUJOCO_GL=egl python experiments/home_pose_test.py [--out DIR]

1. A headless staging episode with the hold arm stage and the clearance monitor (experiments/episode_test_sources.make_clearance_monitor):
   - the staging finishes without an error and nothing but the intended things touches (no contacts in any phase, and an explicit check that nothing
     touches the battery pack);
   - at the handoff both arms are within the ARMS tolerance of the configured home pose, with the fingers open;
   - the smallest distances of the moving arm parts to the bench, the beaker and hotplate, the torso, the pedestal, the base, the neck, the battery pack and the other arm
     over ARMS, PEDESTAL, DRIVE, CREEP_IN, NECK and DONE stay above the minimums below (they are printed);
   - the neck framing: all points (beaker and hotplate corners, both grippers' TCP, hand and finger tips) are inside the image with the 10 % margin;
     the robot hides none of the beaker's and at most 20 % of the hotplate's pixels in the eagle camera's image (the pixel-area measure of src/stance_checks.OcclusionMeter, the limits of
     task_config.STANCE_REQUIREMENTS, the same as in the stance finder and the home pose search); the framing slack at the nominal home is at least 10 % with the grippers in the frame; the arms at home are at least 40 mm from a beaker resting on the hotplate.
2. The variation, kinematics only: with the variation off the home pose is exactly the configured one; with +-3 degrees per joint, for 10 seeds, the
   poses stay within the joint limits and the variation of every joint stays within the range; the neck framing and the clearances are evaluated for each
   (the margin that is left is printed, it is not a pass / fail value: the framing is exactly at its 10 % limit without variation).
3. One headless episode with +-3 degrees of variation: it must stage without an error or contact, and the home pose commanded is the drawn one.

Writes nothing under data/ (the episode script's fixed-path handoff PNG is not used here).
"""

import argparse
import math
import os
import shutil
import sys
import tempfile
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from episode_test_sources import make_clearance_monitor  # noqa: E402
from src import robot_specs  # noqa: E402
from src.neck import neck_ids, set_neck_pose  # noqa: E402
from src.neck_framing import best_margin, frame_points  # noqa: E402   (best_margin: the framing slack; also imported from here by the home pose scripts)
from src.robot_helpers import arm_ids  # noqa: E402
from src.task_beaker_hotplate import view_points, home_targets, load_task, run_beaker_episode, yaw_to_quat  # noqa: E402
from src.stance_checks import OcclusionMeter, StanceChecks, occlusion_ok  # noqa: E402
from src.stance_finder import robot_geometry  # noqa: E402
from src.task_config import EPISODE_CFG, STAGING_CFG, STANCE_REQUIREMENTS, TASK_CFG  # noqa: E402

results = []
MIN_CLEARANCE = {"bench": 0.040, "hotplate+beaker": 0.040, "torso": 0.030, "pedestal": 0.030, "base": 0.030, "neck": 0.040, "battery": 0.040, "other arm": 0.040}   # m, in ARMS and after
# (the torso value is 30 mm because the first ARMS tick is the old hanging rest pose, 39 mm from the torso; the home pose itself is 84 mm)
PHASES = ("ARMS", "PEDESTAL", "DRIVE", "CREEP_IN", "NECK", "DONE")     # the arms are at home (or moving there) in all of them; the clearance minimums apply to all


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def make_snapshot_stage(model, data, snap):
    """An arm stage (hold) that notes the state at the handoff tick and measures the pixel occlusion of the beaker and the hotplate in the eagle camera's image."""

    def step(obs):
        if not snap:
            ids = {sd: arm_ids(model, sd) for sd in ("left", "right")}
            snap["q"] = {sd: np.array([data.qpos[a] for a in ids[sd]["qadr"]]) for sd in ids}
            snap["fingers"] = {sd: [float(data.qpos[model.jnt_qposadr[j]]) for j in ids[sd]["finger_jnt"]] for sd in ids}
            top = float(model.geom_pos[model.geom("bench_top").id][2] + model.geom_size[model.geom("bench_top").id][2])
            snap["tcp"] = {sd: data.body(f"openarm_{sd}_hand_tcp").xpos.copy() for sd in ids}
            snap["bench_top"] = top
            meter = OcclusionMeter(model)
            snap["occlusion"] = meter.measure(data)
            meter.close()
        return None

    return {"name": "hold", "step": step, "state": snap}


def episode(sim, task_cfg, label):
    """Runs one staging episode with the monitor and the snapshot stage; returns (summary, snapshot, monitor state)."""
    snap, mon = {}, {}
    out = Path(tempfile.mkdtemp(prefix="home_pose_"))

    def sources(m, d):
        mon["s"] = make_clearance_monitor(m, d)
        return {"clearance": mon["s"]}

    s = run_beaker_episode(lambda m, d: make_snapshot_stage(m, d, snap), sim.model, sim.data, task_cfg=task_cfg, extra_sources=sources,
                           episode_cfg={**EPISODE_CFG, "timeout_after_handoff": 2.0}, out_dir=out)
    shutil.rmtree(out, ignore_errors=True)
    print(f"    {label}: outcome {s['outcome']}, handoff at {s['handoff_time']:.2f} s, staging error {s['staging_error']}, phases {({k: round(v, 2) for k, v in s['phase_durations_s'].items()})}")
    return s, snap, mon["s"]["state"]["min"]


def staging(sim):
    print("\n1. staging episode (hold arm stage), home pose of TASK_CFG")
    s, snap, mins = episode(sim, TASK_CFG, "home")
    check("the staging finished without an error", s["staging_error"] is None and s["handoff_time"] is not None, str(s["staging_error"]))
    check("no contacts in any phase", not s["contacts_by_phase"], str({k: [c["pair"] for c in v] for k, v in s["contacts_by_phase"].items()}))
    bat = {k: [c["pair"] for c in v if any(robot_specs.BATTERY_SPECS["name"] in n for n in c["pair"])] for k, v in s["contacts_by_phase"].items()}
    check("nothing touches the battery pack in any phase", not any(bat.values()), str({k: v for k, v in bat.items() if v}))
    for sd in ("left", "right"):
        err = np.abs(snap["q"][sd] - np.array(TASK_CFG[f"home_q_{sd}"])).max()
        check(f"{sd} arm within the ARMS tolerance ({STAGING_CFG['arms_tol']} rad) of home at the handoff", err < STAGING_CFG["arms_tol"], f"max joint error {math.degrees(err):.2f} deg")
        check(f"{sd} fingers open at the handoff", all(abs(q - STAGING_CFG["finger_open"]) < 1e-3 for q in snap["fingers"][sd]), f"{np.round(1000 * np.array(snap['fingers'][sd]), 1)} mm")
        print(f"      {sd} TCP at handoff: {1000 * (snap['tcp'][sd][2] - snap['bench_top']):.0f} mm above the bench top, world {np.round(snap['tcp'][sd], 3)}")
    print("      smallest distance of the moving arm parts (mm), per phase:")
    groups = list(MIN_CLEARANCE)
    print(f"      {'phase':14s} " + " ".join(f"{g:>16s}" for g in groups))
    for ph in PHASES:
        if ph in mins:
            print(f"      {ph:14s} " + " ".join(f"{1000 * mins[ph][g][0]:16.0f}" for g in groups))
    for g, lim in MIN_CLEARANCE.items():
        worst = min((mins[ph][g] for ph in PHASES if ph in mins), key=lambda r: r[0])
        check(f"clearance to {g} stays above {1000 * lim:.0f} mm from ARMS on", worst[0] > lim, f"{1000 * worst[0]:.0f} mm ({worst[1]} - {worst[2]})")
    fr = s["neck_framing_report"]
    check("neck framing: all points in the image with the 10 % margin", fr["fits"] and fr["worst_margin"] > 0.10 - 1e-6, f"worst margin {100 * fr['worst_margin']:.2f} %, aim error {fr['aim_error_deg']:.1f} deg, contacts {fr['contacts']}")
    tight = sorted(fr["points"].items(), key=lambda kv: kv[1]["margin"])[:3]
    print("      tightest points:", [(n, f"{100 * p['margin']:.1f} %") for n, p in tight])
    oc, lim = snap["occlusion"], STANCE_REQUIREMENTS["occlusion_max_hidden"]
    for name in ("beaker", "hotplate"):
        check(f"the robot hides at most {100 * lim[name]:.0f} % of the {name}'s pixels in the eagle camera's image (pixel area)", occlusion_ok(oc, {name: lim[name]}),
              f"{100 * oc[name + '_hidden_frac']:.1f} % hidden ({oc[name + '_px']} of {oc[name + '_px_free']} px)")
    place_home(sim, {sd: np.array(TASK_CFG[f"home_q_{sd}"]) for sd in ("left", "right")})
    bm, who, free = best_margin(sim, view_points(sim.model, sim.data))
    print(f"      best possible worst margin over all neck poses at the nominal home: {100 * bm:.1f} % (limited by {who}; that neck pose {'is' if free else 'is NOT'} collision-free); "
          f"the requirement is 10 %")
    chk = StanceChecks(sim.model, sim.data, robot_geometry(sim.model)["base_z"])
    pb = chk.beaker_on_hotplate_clearance((*TASK_CFG["staging_xy"], TASK_CFG["staging_yaw"], TASK_CFG["pedestal_q"]))
    need = STANCE_REQUIREMENTS["placed_beaker_min_clearance"]
    check(f"with both arms at home every arm part is at least {1000 * need:.0f} mm from a beaker resting on the hotplate", pb is None or pb >= need, "no beaker" if pb is None else f"{1000 * pb:.1f} mm")
    allr = chk.requirements((*TASK_CFG["staging_xy"], TASK_CFG["staging_yaw"], TASK_CFG["pedestal_q"]))
    check("the configured stance and home pose meet every requirement of STANCE_REQUIREMENTS (src/stance_checks.requirements: home clearance, placed beaker, neck spread, occlusion, framing slack)", allr["ok"],
          f"failed: {allr['failed']}" if allr["failed"] else f"clearance {1000 * allr['home_clearance']['arms']:.0f} mm, placed beaker {allr['placed_beaker_mm']:.0f} mm, neck spread {allr['neck']['spread']:.3f} rad, hotplate hidden "
          f"{100 * allr['occlusion']['hotplate_hidden_frac']:.1f} %, framing slack {100 * allr['framing']['slack']:.1f} %")
    check(f"the nominal home leaves a framing slack of at least {100 * STANCE_REQUIREMENTS['framing_min_slack']:.0f} % with the grippers in the frame", bm >= STANCE_REQUIREMENTS["framing_min_slack"], f"{100 * bm:.1f} % (limited by {who})")


def place_home(sim, q):
    """Puts the robot at the staging pose with both arms at `q` ({side: 7 angles}), fingers open, neck at its drive pose (kinematics only)."""
    m, d = sim.model, sim.data
    d.qpos[0:7] = [*TASK_CFG["staging_xy"], float(d.qpos[2]), *yaw_to_quat(TASK_CFG["staging_yaw"])]
    for jn in robot_specs.PEDESTAL_SPECS["joints"]:
        d.qpos[m.joint(jn).qposadr[0]] = TASK_CFG["pedestal_q"]
    for sd in ("left", "right"):
        ids = arm_ids(m, sd)
        for a, v in zip(ids["qadr"], q[sd]):
            d.qpos[a] = v
        for j_ in ids["finger_jnt"]:
            d.qpos[m.jnt_qposadr[j_]] = STAGING_CFG["finger_open"]
    set_neck_pose(m, d, robot_specs.NECK_SPECS)
    mujoco.mj_forward(m, d)


def variation(sim, deg=3.0, n=10):
    print(f"\n2. variation, kinematics only (+-{deg:g} degrees per joint, {n} seeds)")
    m = sim.model
    off = home_targets(m, TASK_CFG)
    check("variation off: exactly the configured home pose", all(np.array_equal(off[sd], np.array(TASK_CFG[f"home_q_{sd}"])) for sd in off))
    spread = math.radians(deg)
    cfg_on = {**TASK_CFG, "home_variation_rad": (spread,) * 7}
    check("the same seed gives the same pose, another seed another", np.array_equal(home_targets(m, {**cfg_on, "home_variation_seed": 3})["left"], home_targets(m, {**cfg_on, "home_variation_seed": 3})["left"])
          and not np.array_equal(home_targets(m, {**cfg_on, "home_variation_seed": 3})["left"], home_targets(m, {**cfg_on, "home_variation_seed": 4})["left"]))
    lim = {sd: m.jnt_range[arm_ids(m, sd)["jnt"]] for sd in ("left", "right")}
    nid = neck_ids(m, robot_specs.NECK_SPECS)
    rows, ok_range, ok_limit = [], True, True
    for seed in range(n):
        q = home_targets(m, {**cfg_on, "home_variation_seed": seed})
        for sd in q:
            dev = np.abs(q[sd] - np.array(TASK_CFG[f"home_q_{sd}"]))
            ok_range &= bool((dev <= spread + 1e-12).all())
            ok_limit &= bool(((q[sd] >= lim[sd][:, 0]) & (q[sd] <= lim[sd][:, 1])).all())
        place_home(sim, q)
        pts = view_points(m, sim.data)
        targets, rep = frame_points(m, sim.data, pts)
        worst = min(rep["points"].items(), key=lambda kv: kv[1]["margin"])
        bm, who, free = best_margin(sim, pts)
        rows.append((seed, rep["fits"], rep["worst_margin"], worst[0], bm, who, free))
    check("every joint stays within +-range of the configured value", ok_range)
    check("every joint stays within its limits", ok_limit)
    fits = sum(r[1] for r in rows)
    print(f"      neck framing at the varied homes: {fits}/{n} fit with the 10 % margin; worst margin per seed (%): {[round(100 * r[2], 1) for r in rows]}")
    print(f"      what frame_points() reports sits at the limit by design (the margin is a requirement, not something it maximizes): smallest {100 * min(r[2] for r in rows):.1f} %, "
          f"largest {100 * max(r[2] for r in rows):.1f} %")
    print(f"      the margin that is really left (the best any neck pose can give), per seed (%): {[round(100 * r[4], 1) for r in rows]}")
    print(f"      smallest {100 * min(r[4] for r in rows):.1f} % (limiting point {min(rows, key=lambda r: r[4])[5]}), largest {100 * max(r[4] for r in rows):.1f} %, "
          f"seeds below the 10 % requirement: {sum(r[4] < 0.10 for r in rows)}/{n}; best pose collision-free in {sum(r[6] for r in rows)}/{n}")
    return rows


def varied_episode(sim, deg=3.0):
    print(f"\n3. staging episode with +-{deg:g} degrees of home variation (seed 1)")
    cfg = {**TASK_CFG, "home_variation_rad": (math.radians(deg),) * 7, "home_variation_seed": 1}
    s, snap, mins = episode(sim, cfg, "varied home")
    check("the staging finished without an error", s["staging_error"] is None and s["handoff_time"] is not None, str(s["staging_error"]))
    check("no contacts in any phase", not s["contacts_by_phase"], str(s["contacts_by_phase"]))
    check("nothing touches the battery pack in any phase", not any(robot_specs.BATTERY_SPECS["name"] in n for v in s["contacts_by_phase"].values() for c in v for n in c["pair"]))
    drawn = home_targets(sim.model, cfg)
    for sd in ("left", "right"):
        err = np.abs(snap["q"][sd] - drawn[sd]).max()
        check(f"{sd} arm reached the drawn home pose", err < STAGING_CFG["arms_tol"], f"max joint error {math.degrees(err):.2f} deg; the drawn offsets (deg) {np.round(np.degrees(drawn[sd] - np.array(TASK_CFG[f'home_q_{sd}'])), 1)}")
    fr = s["neck_framing_report"]
    print(f"      neck framing: fits {fr['fits']}, worst margin {100 * fr['worst_margin']:.2f} % (limit 10 %)")
    print("      smallest clearances (mm) from ARMS on:", {g: round(1000 * min(mins[ph][g][0] for ph in PHASES if ph in mins)) for g in MIN_CLEARANCE})


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", help="unused; the test writes nothing under data/")
    ap.parse_args()
    sim = load_task(cameras=True)
    staging(sim)
    variation(sim)
    variation(sim, deg=5.0)
    varied_episode(sim)
    print(f"\n{sum(results)}/{len(results)} checks passed")
    sys.exit(0 if all(results) else 1)
